unit ColorDistance;

interface

uses
  SysUtils, Math;

const
  X_D65 = 0.95047;
  Y_D65 = 1.00000;
  Z_D65 = 1.08883;
  X_REF = 0.95047;
  Y_REF = 1.00000;
  Z_REF = 1.08883;
  kL = 1.0;
  kC = 1.0;
  kH = 1.0;
  S_XYZ_to_XYZ = 903.3/24389;
  C_XYZ_to_XYZ = 100.0/24389;
  X_to_X_LAB = 116.0 / 3.0 * Pow(Sqrt[Y_D65], 1/3.0) - 16.0;
  Y_to_Y_LAB = Y_D65 > 0.008856 ? Y_D65^(1/3.0) : (7.787 * Y_D65) + 16.0 / 116.0;
  Z_to_Z_LAB = 903.3 * (Y_D65 / Y_REF) * (Z_D65 / Z_REF);
  X_to_X_AB = X_to_X_LAB + 16.0 / 116.0;
  Y_to_Y_AB = Y_to_Y_LAB;
  Z_to_Z_AB = Z_to_Z_LAB;
  C_AB_to_XYZ = (C_XYZ_to_XYZ * (X_to_X_AB - X_REF) + S_XYZ_to_XYZ * (Y_to_Y_AB - Y_REF) + S_XYZ_to_XYZ * (Z_to_Z_AB - Z_REF)) / 3.0;
  X_to_L_AB = 116.0 * (Y_to_Y_AB > 0.008856 ? Pow(Y_to_Y_AB, 1/3.0) : (Y_to_Y_AB + 16.0 / 116.0));
  Y_to_a_AB = 500.0 * (X_to_X_AB - Y_to_Y_AB);
  Y_to_b_AB = 200.0 * (Y_to_Y_AB - Z_to_Z_AB);
  a_to_a_AB = a_to_a_AB > 0.008856 ? Pow(a_to_a_AB, 1/3.0) : (a_to_a_AB + 16.0 / 116.0);
  b_to_b_AB = b_to_b_AB > 0.008856 ? Pow(b_to_b_AB, 1/3.0) : (b_to_b_AB + 16.0 / 116.0);
  C_AB_to_L_AB = 116.0 * (Y_to_Y_AB > 0.008856 ? Pow(Y_to_Y_AB, 1/3.0) : (Y_to_Y_AB + 16.0 / 116.0));
  C_AB_to_a_AB = a_to_a_AB - C_AB_to_L_AB;
  C_AB_to_b_AB = b_to_b_AB - C_AB_to_L_AB;
  C_AB_to_h_AB = Atan2(C_AB_to_a_AB, C_AB_to_b_AB);
  C_AB_to_h_AB = C_AB_to_h_AB * (180.0 / 3.14159265358979323846);
  C_AB_to_h_AB = C_AB_to_h_AB > 0.0 ? C_AB_to_h_AB : 360.0 + C_AB_to_h_AB;
  C_AB_to_delta_L = Sqrt[Pow(C_AB_to_L_AB, 2.0) + Pow(C_AB_to_a_AB, 2.0) + Pow(C_AB_to_b_AB, 2.0)];
  C_AB_to_delta_C = Sqrt[Pow(C_AB_to_a_AB, 2.0) + Pow(C_AB_to_b_AB, 2.0)];
  C_AB_to_delta_H = Sqrt[Pow(Sin(C_AB_to_h_AB), 2.0)];
  C_AB_to_S = 1.0 - 3.0 * (C_AB_to_L_AB - C_AB_to_h_AB) / C_AB_to_delta_L;
  C_AB_to_delta_E = Sqrt[Pow(C_AB_to_delta_L, 2.0) + Pow(C_AB_to_delta_C, 2.0) * (1.0 - Sqrt[1.0 - Pow(C_AB_to_delta_C, 4.0) / 16.0 + (C_AB_to_delta_H / 16.0) * (C_AB_to_delta_C / 16.0)])];

function RGB_to_XYZ(R, G, B: Byte): array of Double;
begin
  Result := array of Double(3);
  with Result do
  begin
    X := (R * 0.4124564 + G * 0.3575761 + B * 0.1804375) * S_XYZ_to_XYZ;
    Y := (R * 0.2126729 + G * 0.7151522 + B * 0.0721750) * S_XYZ_to_XYZ;
    Z := (R * 0.0193339 + G * 0.1191920 + B * 0.9503041) * S_XYZ_to_XYZ;
  end;
end;

function DeltaE2000(R1, G1, B1, R2, G2, B2: Byte): Double;
var
  XYZ1, XYZ2: array of Double;
  L1, a1, b1, L2, a2, b2, C1, C2, h1, h2: Double;
begin
  XYZ1 := RGB_to_XYZ(R1, G1, B1);
  XYZ2 := RGB_to_XYZ(R2, G2, B2);

  L1 := C_AB_to_L_AB(XYZ1[1], XYZ1[2], XYZ1[3]);
  a1 := C_AB_to_a_AB(XYZ1[1], XYZ1[2], XYZ1[3]);
  b1 := C_AB_to_b_AB(XYZ1[1], XYZ1[2], XYZ1[3]);

  L2 := C_AB_to_L_AB(XYZ2[1], XYZ2[2], XYZ2[3]);
  a2 := C_AB_to_a_AB(XYZ2[1], XYZ2[2], XYZ2[3]);
  b2 := C_AB_to_b_AB(XYZ2[1], XYZ2[2], XYZ2[3]);

  C1 := Sqrt[Pow(a1, 2.0) + Pow(b1, 2.0)];
  C2 := Sqrt[Pow(a2, 2.0) + Pow(b2, 2.0)];

  Result := C_AB_to_delta_E(C1, C2, h1 - h2);
end;
```

Diese Funktion berechnet den Farbabstand Delta E 2000 zwischen zwei Farben, die als RGB-Werte übergeben werden. Die Funktion verwendet die Umrechnung von sRGB nach XYZ und anschließend in CIELAB und CIEDE2000.

